}

/// Owned handle to a Solidity ABI `string` payload stored in linear memory.
///
/// `data` points at the ABI tail payload: the length word followed by packed
/// UTF-8 bytes padded to a whole word count.
pub struct DynString {
    data: *u8,
    len: u256,
    size: u256,
}

impl DynString {
    pub fn empty() -> Self {
        let data = ptr::alloc_bytes(32)
        store_word(ptr: data, value: 0)
        Self::from_validated_abi_tail(data: data, len: 0, size: 32)
    }

    fn from_validated_abi_tail(data: *u8, len: u256, size: u256) -> Self {
        DynString { data, len, size }
    }

    pub fn from_abi_tail(data: *u8, len: u256, size: u256) -> Self {
        let expected_size = 32 + round_up_words(len)
        if size != expected_size || mem_word_at(base: data, offset: 0) != len {
            super::panic()
        }
        Self::from_validated_abi_tail(data, len, size)
    }

    /// Allocates a string of `len` zero bytes, to be filled through `payload_span`.
    pub fn zeroed(_ len: u256) -> Self {
        let size = 32 + round_up_words(len)
        let data = ptr::alloc_bytes(size)
        ptr::zero_bytes(data, size)
        store_word(ptr: data, value: len)
        Self::from_validated_abi_tail(data: data, len: len, size: size)
    }

    /// Returns the string made of the first `len` bytes of `word` (at most 32),
    /// e.g. a `bytes32` label.
    pub fn from_word_prefix(word: u256, len: u256) -> Self {
        let bytes = Bytes::from_word_prefix(word, len)
        Self::from_validated_abi_tail(data: bytes.data, len: bytes.len, size: bytes.size)
    }

    /// Returns a copy of the `len` bytes starting at `start`.
    ///
    /// Fails with an index-out-of-bounds panic if the range exceeds the string.
    pub fn slice(self, start: u256, len: u256) -> Self {
        Self::from_payload(source: self.payload_span().slice(offset: start, len))
    }

    pub fn from_payload(source: ptr::MemSpan) -> Self {
        let len = source.len()
        let size = 32 + round_up_words(len)
        let data = ptr::alloc_bytes(size)
        ptr::zero_bytes(data, size)
        store_word(ptr: data, value: len)
        ptr::copy(dest: ptr::offset_bytes(data, 32), source)
        Self::from_validated_abi_tail(data: data, len: len, size: size)
    }

    pub fn len(self) -> u256 {
        self.len
    }

    pub fn is_empty(self) -> bool {
        self.len == 0
    }

    pub fn encoded_size(self) -> u256 {
        self.size
    }

    pub fn payload_span(self) -> ptr::MemSpan {
        ptr::MemSpan::from_raw_parts(
            ptr: ptr::offset_bytes(self.data, 32),
            len: self.len,
        )
    }

    pub fn encoded_span(self) -> ptr::MemSpan {
        ptr::MemSpan::from_raw_parts(ptr: self.data, len: self.size)
    }

    pub fn as_bytes(self) -> Bytes {
        Bytes::from_validated_abi_tail(
            data: self.data,
            len: self.len,
            size: self.size,
        )
    }

    pub fn view(self) -> StringView<ptr::MemSpan> {
        StringView {
            bytes: self.as_bytes().view(),
        }
    }

    pub fn byte_at(self, _ index: u256) -> u8 {
        self.view().byte_at(index)
    }
}

/// Owned handle to a Solidity ABI `bytes` payload stored in linear memory.
///
/// `data` points at the ABI tail payload: the length word followed by packed
/// bytes data padded to a whole word count.
pub struct Bytes {
    data: *u8,
    len: u256,
    size: u256,
}

impl Bytes {
    pub fn empty() -> Self {
        let data = ptr::alloc_bytes(32)
        store_word(ptr: data, value: 0)
        Self::from_validated_abi_tail(data: data, len: 0, size: 32)
    }

    fn from_validated_abi_tail(data: *u8, len: u256, size: u256) -> Self {
        Bytes { data, len, size }
    }

    pub fn from_abi_tail(data: *u8, len: u256, size: u256) -> Self {
        let expected_size = 32 + round_up_words(len)
        if size != expected_size || mem_word_at(base: data, offset: 0) != len {
            super::panic()
        }
        Self::from_validated_abi_tail(data, len, size)
    }

    pub fn from_payload(source: ptr::MemSpan) -> Self {
        let len = source.len()
        let size = 32 + round_up_words(len)
        let data = ptr::alloc_bytes(size)
        ptr::zero_bytes(data, size)
        store_word(ptr: data, value: len)
        ptr::copy(dest: ptr::offset_bytes(data, 32), source)
        Self::from_validated_abi_tail(data: data, len: len, size: size)
    }

    /// Build up to 32 bytes from the most-significant bytes of one word.
    pub fn from_word_prefix(word: u256, len: u256) -> Self {
        if len > 32 {
            super::panic()
        }
        if len == 0 {
            return Self::empty()
        }

        let data = ptr::alloc_bytes(64)
        store_word(ptr: data, value: len)
        let shift = (32 - len) * 8
        store_word(
            ptr: ptr::offset_bytes(data, 32),
            value: word >> shift << shift,
        )
        Self::from_validated_abi_tail(data: data, len: len, size: 64)
    }

    pub fn len(self) -> u256 {
        self.len
    }

    pub fn is_empty(self) -> bool {
        self.len == 0
    }

    pub fn encoded_size(self) -> u256 {
        self.size
    }

    #[inline(always)]
    fn payload_ptr(self) -> *u8 {
        ptr::offset_bytes(self.data, 32)
    }

    #[inline(always)]
    pub fn payload_span(self) -> ptr::MemSpan {
        ptr::MemSpan::from_raw_parts(ptr: self.payload_ptr(), len: self.len)
    }

    #[inline(always)]
    pub fn encoded_span(self) -> ptr::MemSpan {
        ptr::MemSpan::from_raw_parts(ptr: self.data, len: self.size)
    }

    #[inline(always)]
    pub fn view(self) -> BytesView<ptr::MemSpan> {
        BytesView {
            input: self.payload_span(),
            start: 0,
            len: self.len,
        }
    }

    #[inline(always)]
    pub fn word_at(self, _ offset: u256) -> u256 {
        self.view().word_at(offset)
    }

    pub fn byte_at(self, _ index: u256) -> u8 {
        self.view().byte_at(index)
    }
}

fn mem_word_load() -> u256
    uses (slot: u256)
{
    slot
}

// Compares byte payloads a word at a time. Payloads of `Bytes` and `DynString`
// are padded to whole words, so the final word read stays inside the value.
fn payload_eq(_ a: ptr::MemSpan, _ b: ptr::MemSpan) -> bool {
    let len = a.len()
    if len != b.len() {
        return false
    }
    let mut offset: u256 = 0
    while offset + 32 <= len {
        if mem_word_at(base: a.ptr(), offset) != mem_word_at(base: b.ptr(), offset) {
            return false
        }
        offset += 32
    }
    let tail = len - offset
    if tail == 0 {
        return true
    }
    let shift = (32 - tail) * 8
    (mem_word_at(base: a.ptr(), offset) >> shift) == (mem_word_at(base: b.ptr(), offset) >> shift)
}

impl Eq for Bytes {
    fn eq(self, _ other: Bytes) -> bool {
        payload_eq(self.payload_span(), other.payload_span())
    }
}

impl Eq for DynString {
    fn eq(self, _ other: DynString) -> bool {
        payload_eq(self.payload_span(), other.payload_span())
    }
}

#[inline(always)]
fn mem_word_at(base: *u8, offset: u256) -> u256 {
    let word_ptr = ptr::cast<u8, u256>(ptr::offset_bytes(base, offset))
    with (word_ptr) {
        mem_word_load()
    }
}

impl ByteInput for ptr::MemSpan {
    fn len(self) -> u256 {
        self.len()
    }

    #[arithmetic(unchecked)]
    #[inline(always)]
    fn word_at(self, _ byte_offset: u256) -> u256 {
        mem_word_at(base: self.ptr(), offset: byte_offset)
    }

    #[arithmetic(unchecked)]
    fn byte_at(self, _ byte_offset: u256) -> u8 {
        let word_offset = byte_offset - (byte_offset % 32)
        let word = mem_word_at(base: self.ptr(), offset: word_offset)
        let idx = byte_offset - word_offset
        let shift = (31 - idx) * 8
        (word >> shift).downcast_truncate()
    }

    fn copy_to_memory(self, dest: *u8, src_offset: u256, len: u256) {
        if src_offset > self.len() || len > self.len() - src_offset {
            super::panic()
        }

        ptr::copy(
            dest,
            source: ptr::MemSpan::from_raw_parts(
                ptr: ptr::offset_bytes(self.ptr(), src_offset),
                len,
            ),
        )
    }

    fn copy_to_memory_unchecked(self, dest: *u8, src_offset: u256, len: u256) {
        ptr::copy(
            dest,
            source: ptr::MemSpan::from_raw_parts(
                ptr: ptr::offset_bytes(self.ptr(), src_offset),
                len,
            ),
        )
    }
}

/// Owned handle to a Solidity-style dynamic array (`T[]`) stored in linear memory.
///
/// `data` points at the ABI payload for the array: the length word followed by the
/// tuple-encoded element heads/tails.
pub struct DynArray<T> {
    data: *u8,
    len: u256,
    size: u256,
}

impl<T> DynArray<T> {
    pub fn empty() -> Self {
        let data = ptr::alloc_bytes(32)
        store_word(ptr: data, value: 0)
        Self::from_validated_abi_tail(data: data, len: 0, size: 32)
    }

    fn from_validated_abi_tail(data: *u8, len: u256, size: u256) -> Self {
        DynArray { data, len, size }
    }

    /// Construct an array handle over a complete ABI tail.
    ///
    /// `data` must point to `size` valid bytes. Static-element arrays are
    /// validated exactly; callers constructing dynamic-element arrays must
    /// ensure their nested tails are valid and end at `size`.
    pub fn from_abi_tail(data: *u8, len: u256, size: u256) -> Self
        where T: AbiSize
    {
        let minimum_size = 32 + (len * abi_field_head_size<T>())
        if size < 32
            || size % 32 != 0
            || size < minimum_size
            || (!T::IS_DYNAMIC && size != minimum_size)
            || (len == 0 && size != 32)
            || mem_word_at(base: data, offset: 0) != len
        {
            super::panic()
        }
        Self::from_validated_abi_tail(data, len, size)
    }

    pub fn len(self) -> u256 {
        self.len
    }

    pub fn is_empty(self) -> bool {
        self.len == 0
    }

    pub fn encoded_size(self) -> u256 {
        self.size
    }

    pub fn encoded_span(self) -> ptr::MemSpan {
        ptr::MemSpan::from_raw_parts(ptr: self.data, len: self.size)
    }
}

impl AbiSize for u256 {
    const HEAD_SIZE: u256 = 32
    const IS_DYNAMIC: bool = false
}

impl<const N: usize> AbiSize for String<N> {
    const HEAD_SIZE: u256 = 32
    const IS_DYNAMIC: bool = true

    fn payload_size(self) -> u256 {
        // A packed string occupies at most one ABI data word.
        if self.to_word() == 0 { 32 } else { 64 }
    }
}

impl<T, const N: usize> AbiSize for [T; N]
    where T: AbiSize + Copy
{
    const HEAD_SIZE: u256 = (N as u256) * abi_field_head_size<T>()
    const IS_DYNAMIC: bool = T::IS_DYNAMIC

    fn payload_size(self) -> u256 {
        if !T::IS_DYNAMIC {
            return Self::HEAD_SIZE
        }

        let mut total = Self::HEAD_SIZE
        let mut i: usize = 0
        while i < N {
            total += self[i].payload_size()
            i += 1
        }
        total
    }
}

