    pub const fn leading_zeros(_ x: u256) -> u256
}

/// Returns the number of trailing zero bits in `x`, or 256 if `x == 0`.
#[arithmetic(unchecked)]
pub const fn trailing_zeros(_ x: u256) -> u256 {
    if x == 0 {
        return 256
    }
    // `x & -x` isolates the lowest set bit.
    255 - leading_zeros(x & (0 - x))
}

