        if self == isize::min() { isize::max() } else if self < 0 { -self } else { self }
    }
    const fn overflowing_abs(self) -> (isize, bool) {
        if self == isize::min() { (isize::min(), true) } else if self < 0 { (-self, false) } else { (self, false) }
    }
}

