            self.truncate(len: offset),
            self.slice(offset, len: self.len - offset),
        )
    }

    pub fn truncate(self, len: u256) -> Self {
        self.slice(offset: 0, len)
    }

    pub fn ptr_at(self, _ index: u256) -> *T {
        if index >= self.len {
            index_out_of_bounds()
        }
        offset(self.ptr, index)
    }

    pub fn get(self, _ index: u256) -> Option<T>
        where T: Copy
    {
        if index >= self.len() {
            return Option::None
        }
        Option::Some(*self.ptr_at(index))
    }
