        match self.get(index) {
            Option::Some(value) => value
            Option::None => index_out_of_bounds()
        }
    }
}

impl MemBuffer {
    pub fn alloc(_ len: u256) -> Self {
        Self {
            ptr: alloc_raw(len),
            len,
            capacity: len,
        }
    }

    pub fn with_capacity(_ capacity: u256) -> Self {
        Self {
            ptr: alloc_raw(capacity),
            len: 0,
            capacity,
        }
    }

    pub fn empty() -> Self {
        Self::with_capacity(0)
    }

    pub fn from_span(_ source: own MemSpan) -> Self {
        let mut buffer = Self::with_capacity(source.len())
        buffer.extend_from(source)
        buffer
    }

    pub fn ptr(self) -> *u8 {
        self.ptr
    }

    pub fn len(self) -> u256 {
        self.len
    }

    pub fn capacity(self) -> u256 {
        self.capacity
    }

    pub fn remaining_capacity(self) -> u256 {
        self.capacity - self.len
    }

    /// View the logical byte extent.
    pub fn span(self) -> MemSpan {
        MemSpan::from_raw_parts(ptr: self.ptr, len: self.len)
    }

    /// View the full allocation, including bytes beyond the logical extent.
    ///
    /// Callers must initialize those additional bytes before reading the span.
    pub fn capacity_span(self) -> MemSpan {
        MemSpan::from_raw_parts(ptr: self.ptr, len: self.capacity)
    }

    pub fn slice(self, offset: u256, len: u256) -> MemSpan {
        self.span().slice(offset, len)
    }

    /// Ensure that `additional` bytes fit after the logical extent.
    ///
    /// Linear-memory allocations cannot grow in place, so growth allocates a
    /// larger region and copies the initialized bytes.
    pub fn reserve(mut self, _ additional: u256) {
        let needed = self.len + additional
        if needed <= self.capacity {
            return
        }

        let mut capacity = self.capacity
        if capacity == 0 {
            capacity = 32
        }
        while capacity < needed {
            capacity *= 2
        }

        let replacement = alloc_raw(capacity)
        copy(dest: replacement, source: self.span())
        self.ptr = replacement
        self.capacity = capacity
    }

    /// Append bytes, growing the allocation when necessary.
    pub fn extend_from(mut self, _ source: own MemSpan) {
        self.reserve(source.len())
        copy(dest: offset_bytes(self.ptr, self.len), source)
        self.len += source.len()
    }

    /// Copy bytes into an allocation subrange and extend the logical extent.
    pub fn copy_from(mut self, dest_offset: u256, _ source: own MemSpan) {
        if dest_offset > self.capacity || source.len() > self.capacity - dest_offset {
            index_out_of_bounds()
        }
        if source.is_empty() {
            return
        }
        if dest_offset > self.len {
            zero_bytes(
                ptr: offset_bytes(self.ptr, self.len),
                len: dest_offset - self.len,
            )
        }
        copy(dest: offset_bytes(self.ptr, dest_offset), source)
        let end = dest_offset + source.len()
        if end > self.len {
            self.len = end
        }
    }

    /// Set the logical extent after initializing the added bytes.
    pub fn set_len(mut self, _ len: u256) {
        if len > self.capacity {
            index_out_of_bounds()
        }
        self.len = len
    }

    pub fn truncate(mut self, _ len: u256) {
        if len > self.len {
            index_out_of_bounds()
        }
        self.len = len
    }

    pub fn is_empty(self) -> bool {
        self.len == 0
    }
}

