            len,
        }
    }

    /// Zeroes the allocated bytes. Zero bytes do not establish native references.
    pub fn new_zeroed(_ len: u256) -> Self {
        let mut array = Self::new_uninit(len)
        array.zero()
        array
    }

    pub fn ptr(self) -> *T {
        self.ptr
    }

    pub fn len(self) -> u256 {
        self.len
    }

    pub fn byte_len(self) -> u256 {
        self.len * size_of<T>()
    }

    pub fn into_bytes(own self) -> MemArray<u8> {
        MemArray {
            ptr: cast<T, u8>(self.ptr),
            len: self.byte_len(),
        }
    }

    pub fn as_slice(self) -> MemSlice<T> {
        MemSlice::from_raw_parts(ptr: self.ptr, len: self.len)
    }

    pub fn span(self) -> MemSpan {
        self.as_slice().as_bytes()
    }

    pub fn into_buffer(own self) -> MemBuffer {
        let len = self.byte_len()
