use core::abi::{Abi, AbiDecoder, AbiSize, AbiSpan, ByteInput, Decode, Encode, store_word}
use core::num::IntDowncast
use core::ops::{WrappingAdd, WrappingMul, WrappingSub}
use ingot::evm::{EncodePacked, Packed, RawMem, packed::write_word_prefix, SolPacked, StorageKey, TopicValue, ops::{revert_empty, signextend}}

use super::types::{SolCompat, StaticAbiElement, StaticAbiElementSeal}

const FULL_WORD_MASK: u256 = 0xffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff

#[inline(always)]
fn canonical_unsigned_word(word: u256, bits: u256) -> u256 {
    // Canonical Solidity ABI encoding for an unsigned integer of width `bits`
    // requires that all higher bits are zero.
    //
    // This shift-based check is cheaper than constructing a `(1 << bits) - 1`
    // mask for every call.
    if word >> bits == 0 {
        return word
    }
    revert_empty()
}

#[inline(always)]
fn canonical_custom_signed_word(word: u256, bits: u256) -> u256 {
    // Canonical Solidity ABI encoding for a signed integer of width `bits`
    // requires that all higher bits are a sign-extension of the sign bit.
    if bits == 0 {
        if word == 0 {
            return 0
        }
        revert_empty()
    }

    let sign = (word >> (bits - 1)) & 1
    if sign == 0 {
        if word >> bits == 0 {
            return word
        }
        revert_empty()
    }

    if word >> bits == (FULL_WORD_MASK >> bits) {
        return word
    }
    revert_empty()
}

#[inline(always)]
fn decode_uint_u32(word: u256, bits: u256) -> u32 {
    canonical_unsigned_word(word: word, bits: bits).downcast_unchecked()
}

#[inline(always)]
fn decode_uint_u64(word: u256, bits: u256) -> u64 {
    canonical_unsigned_word(word: word, bits: bits).downcast_unchecked()
}

#[inline(always)]
fn decode_uint_u128(word: u256, bits: u256) -> u128 {
    canonical_unsigned_word(word: word, bits: bits).downcast_unchecked()
}

#[inline(always)]
fn decode_uint_u256(word: u256, bits: u256) -> u256 {
    canonical_unsigned_word(word: word, bits: bits)
}

#[inline(always)]
fn decode_int_i32(word: u256, bits: u256) -> i32 {
    let signed_word: i256 = canonical_custom_signed_word(word: word, bits: bits).downcast_unchecked()
    signed_word.downcast_unchecked()
}

#[inline(always)]
fn decode_int_i64(word: u256, bits: u256) -> i64 {
    let signed_word: i256 = canonical_custom_signed_word(word: word, bits: bits).downcast_unchecked()
    signed_word.downcast_unchecked()
}

#[inline(always)]
fn decode_int_i128(word: u256, bits: u256) -> i128 {
    let signed_word: i256 = canonical_custom_signed_word(word: word, bits: bits).downcast_unchecked()
    signed_word.downcast_unchecked()
}

#[inline(always)]
fn decode_int_i256(word: u256, bits: u256) -> i256 {
    canonical_custom_signed_word(word: word, bits: bits).downcast_unchecked()
}

pub trait SolWordRepr {
    /// Solidity bit width of the type.
    const BITS: u256
    fn canonical_word(self) -> u256
}

trait SolWrappingInt: Copy {
    fn raw_word(self) -> u256
    fn from_wrapping_word(_: u256) -> Self
}

// Sealed marker for the custom-width Solidity int wrappers below. It lets the
// blanket impls of the foreign ABI/event traits (`Encode`, `AbiSize`,
// `AbiSpan`, `TopicValue`, and the `Wrapping*` ops) apply only to these
// newtypes: a private, empty marker whose every impl targets a local nominal
// type is "sealed", which is what makes a local blanket impl of a foreign
// trait admissible. It must stay non-`pub` and be implemented per-type (a
// blanket `impl<T: ..> SolInt for T` would break the sealing), so each wrapper
// has its own `impl SolInt`.
trait SolInt {}

fn wrapping_unsigned_word(word: u256, bits: u256) -> u256 {
    word & (((1 as u256) << bits) - 1)
}

fn wrapping_signed_word(word: u256, bits: u256) -> u256 {
    signextend(byte: (bits / 8) - 1, value: word)
}

fn wrapping_unsigned_u32(word: u256, bits: u256) -> u32 {
    wrapping_unsigned_word(word: word, bits: bits).downcast_unchecked()
}

fn wrapping_unsigned_u64(word: u256, bits: u256) -> u64 {
    wrapping_unsigned_word(word: word, bits: bits).downcast_unchecked()
}

fn wrapping_unsigned_u128(word: u256, bits: u256) -> u128 {
    wrapping_unsigned_word(word: word, bits: bits).downcast_unchecked()
}

fn wrapping_signed_i32(word: u256, bits: u256) -> i32 {
    let signed: i256 = wrapping_signed_word(word: word, bits: bits).downcast_unchecked()
    signed.downcast_unchecked()
}

fn wrapping_signed_i64(word: u256, bits: u256) -> i64 {
    let signed: i256 = wrapping_signed_word(word: word, bits: bits).downcast_unchecked()
    signed.downcast_unchecked()
}

