pub trait Contract {
    /// Constructor argument tuple, ABI-encodable under the default ABI.
    type InitArgs: Encode<Sol>

    /// Offset of this contract's initcode within the current artifact.
    fn init_code_offset() -> u256

    /// Length (in bytes) of this contract's initcode within the current artifact.
    fn init_code_len() -> u256
}

pub trait Create: EvmCapabilitySeal {
    /// Low-level `CREATE` opcode.
    fn create_raw(mut self, value: u256, init_code: MemSpan) -> Address {
        Address { inner: ops::create(value: value, offset: init_code.ptr(), len: init_code.len()) }
    }

    /// Low-level `CREATE2` opcode.
    fn create2_raw(mut self, value: u256, init_code: MemSpan, salt: u256) -> Address {
        Address {
            inner: ops::create2(value: value, offset: init_code.ptr(), len: init_code.len(), salt: salt),
        }
    }

    /// Deploy a high-level contract using `CREATE`, bubbling revert data on failure.
    fn create<C: Contract>(mut self, value: u256, args: own C::InitArgs) -> Address {
        let init_len = C::init_code_len()
        let init_off = C::init_code_offset()
        let mut addr: Address

        if !C::InitArgs::IS_DYNAMIC && C::InitArgs::HEAD_SIZE == 0 {
            let init_code = MemBuffer::alloc(init_len)
            ops::codecopy(dest: init_code.ptr(), offset: init_off, len: init_code.len())
            addr = self.create_raw(value: value, init_code: init_code.span())
        } else {
            let encoded = encode_abi_payload<C::InitArgs>(args)
            let init_code = MemBuffer::alloc(init_len + encoded.len())
            ops::codecopy(dest: init_code.ptr(), offset: init_off, len: init_len)
            ptr::copy(
                dest: ptr::offset_bytes(init_code.ptr(), init_len),
                source: encoded.span(),
            )
            addr = self.create_raw(value: value, init_code: init_code.span())
        }

        // Solidity-style behavior: bubble revert data if creation fails.
        if addr.inner == 0 {
            bubble_last_revert()
        }

        addr
    }

    /// Deploy a high-level contract using `CREATE2`, bubbling revert data on failure.
    fn create2<C: Contract>(mut self, value: u256, args: own C::InitArgs, salt: u256) -> Address {
        let init_len = C::init_code_len()
        let init_off = C::init_code_offset()
        let mut addr: Address

        if !C::InitArgs::IS_DYNAMIC && C::InitArgs::HEAD_SIZE == 0 {
            let init_code = MemBuffer::alloc(init_len)
            ops::codecopy(dest: init_code.ptr(), offset: init_off, len: init_code.len())
            addr = self.create2_raw(value: value, init_code: init_code.span(), salt)
        } else {
            let encoded = encode_abi_payload<C::InitArgs>(args)
            let init_code = MemBuffer::alloc(init_len + encoded.len())
            ops::codecopy(dest: init_code.ptr(), offset: init_off, len: init_len)
            ptr::copy(
                dest: ptr::offset_bytes(init_code.ptr(), init_len),
                source: encoded.span(),
            )
            addr = self.create2_raw(value: value, init_code: init_code.span(), salt)
        }

        // Solidity-style behavior: bubble revert data if creation fails.
        if addr.inner == 0 {
            bubble_last_revert()
        }

        addr
    }
}

#[inline(always)]
pub fn encode_abi_payload<T>(_ value: own T) -> MemBuffer
    where T: Encode<Sol> + AbiSize
{
    encode_alloc<Sol, T>(value)
}

/// Metadata returned by a low-level EVM call.
#[must_use]
pub struct RawCallOutcome {
    success: bool,
    returndata_len: u256,
}

impl Copy for RawCallOutcome {}

impl RawCallOutcome {
    pub fn success(self) -> bool {
        self.success
    }

    /// Full returndata length, which may exceed the output buffer's `len`.
    pub fn returndata_len(self) -> u256 {
        self.returndata_len
    }
}

/// Owned returndata from a typed, non-bubbling EVM call.
///
/// The payload is preserved for both success and failure, so callers can
/// inspect or decode it without relying on the ephemeral returndata buffer.
#[must_use]
pub struct CallOutcome {
    success: bool,
    returndata: MemBuffer,
}

impl CallOutcome {
    pub fn success(self) -> bool {
        self.success
    }

    pub fn returndata(self) -> MemSpan {
        self.returndata.span()
    }

    pub fn returndata_len(self) -> u256 {
        self.returndata.len()
    }

    pub fn into_returndata(own self) -> MemBuffer {
        self.returndata
    }

    /// Strictly decode successful returndata, bubbling preserved revert data
    /// when the call failed.
    pub fn decode<R>(own self) -> R
        where R: Decode<Sol> + AbiSize
    {
        let success = self.success
        let returndata = self.returndata
        if !success {
            ops::revert(offset: returndata.ptr(), len: returndata.len())
        }
        decode_returndata(returndata.span())
    }
}

fn finish_raw_call(_ success: bool, _ ret: mut MemBuffer) -> RawCallOutcome {
    let returndata_len = ops::returndatasize()
    let written = if returndata_len < ret.capacity() {
        returndata_len
    } else {
        ret.capacity()
    }
    ret.set_len(written)
    RawCallOutcome {
        success,
        returndata_len,
    }
}

fn copy_call_outcome(_ raw: RawCallOutcome) -> CallOutcome {
    CallOutcome {
        success: raw.success(),
        returndata: copy_returndata(),
    }
}

fn prepare_copy_destination(
    dest: mut MemBuffer,
    dest_offset: u256,
    len: u256,
) -> *u8 {
    if dest_offset > dest.capacity() || len > dest.capacity() - dest_offset {
        core::panic()
    }
    if len != 0 && dest_offset > dest.len() {
        ptr::zero_bytes(
            ptr: ptr::offset_bytes(dest.ptr(), dest.len()),
            len: dest_offset - dest.len(),
        )
    }
    ptr::offset_bytes(dest.ptr(), dest_offset)
}

/// High-level contract calls with ABI encoding/decoding.
pub trait Call: EvmCapabilitySeal {
    /// Low-level `CALL` opcode with explicit input and output regions.
    ///
    /// The output buffer receives at most its capacity; the outcome retains
    /// the full returndata length.
    fn raw_call(
        mut self,
        addr: Address,
        gas: u256,
        value: u256,
        args: MemSpan,
        ret: mut MemBuffer,
    ) -> RawCallOutcome {
        let success = ops::call(
            gas: gas,
            addr: addr.inner,
            value: value,
            args_offset: args.ptr(),
            args_len: args.len(),
            ret_offset: ret.ptr(),
            ret_len: ret.capacity(),
        ) != 0
        finish_raw_call(success, mut ret)
    }

    /// Call with an explicit gas allotment and a caller reserve. An Err means
    /// the budget was insufficient and no external call was made. Ok contains
    /// EVM success/failure; it does not imply target code exists.
    ///
    /// Input is copied before measuring gas to pay memory expansion up front.
    /// No returndata is copied, so an adversarial return cannot consume the
    /// reserve. The outcome reports its full length. Revert data is not bubbled.
    ///
    /// See calls::has_min_gas for the EIP-150 admission rule and gas-schedule
    /// assumptions. The requested gas is forwarded exactly (plus the EVM's
    /// value stipend); admission is conservative and may reject feasible calls.
    fn call_with_min_gas(
        mut self,
        addr: Address,
        minimum: u256,
        reserved: u256,
        value: u256,
        args: MemSpan,
    ) -> Result<super::calls::InsufficientGas, RawCallOutcome> {
        let input = MemBuffer::from_span(args)
        let mut output = MemBuffer::empty()
        if !super::calls::has_min_gas(ops::gas(), minimum, reserved) {
            return Result::Err(super::calls::InsufficientGas {})
        }
        Result::Ok(
            self.raw_call(
                addr,
                gas: minimum,
                value,
                args: input.span(),
                ret: mut output,
            ),
        )
    }

    /// Low-level `STATICCALL` opcode with explicit input and output buffers.
    ///
    /// The output buffer receives at most its capacity; the outcome retains
    /// the full returndata length.
    fn raw_staticcall(
        self,
        addr: Address,
        gas: u256,
        args: MemSpan,
        ret: mut MemBuffer,
    ) -> RawCallOutcome {
        let success = ops::staticcall(
            gas: gas,
            addr: addr.inner,
            args_offset: args.ptr(),
            args_len: args.len(),
            ret_offset: ret.ptr(),
            ret_len: ret.capacity(),
        ) != 0
        finish_raw_call(success, mut ret)
    }

    /// Low-level `DELEGATECALL` opcode with explicit input and output buffers.
    ///
    /// The output buffer receives at most its capacity; the outcome retains
    /// the full returndata length.
    fn raw_delegatecall(
        mut self,
        addr: Address,
        gas: u256,
        args: MemSpan,
        ret: mut MemBuffer,
    ) -> RawCallOutcome {
        let success = ops::delegatecall(
            gas: gas,
            addr: addr.inner,
            args_offset: args.ptr(),
            args_len: args.len(),
            ret_offset: ret.ptr(),
            ret_len: ret.capacity(),
        ) != 0
        finish_raw_call(success, mut ret)
    }

    /// `CALL` with pre-encoded calldata without bubbling failure.
    ///
    /// The returned owner contains the complete success or revert payload.
    fn try_call_raw(mut self, addr: own Address, gas: u256, value: u256, args: MemSpan) -> CallOutcome {
        let mut ret = MemBuffer::empty()
        let raw = self.raw_call(addr, gas, value, args, ret: mut ret)
        copy_call_outcome(raw)
    }

    /// Perform a typed `CALL` without bubbling failure.
    ///
    /// The returned owner contains the complete success or revert payload.
    fn try_call<M>(
        mut self,
        addr: own Address,
        gas: u256,
        value: u256,
        message: own M,
    ) -> CallOutcome
    where M: MsgVariant<Sol> + Encode<Sol>
    {
        let args = encode_calldata(<M as MsgVariant<Sol>>::SELECTOR, message)
        let mut ret = MemBuffer::empty()
        let raw = self.raw_call(addr, gas, value, args: args.span(), ret: mut ret)
        copy_call_outcome(raw)
    }

    /// Perform a typed `STATICCALL` without bubbling failure.
    fn try_static<M>(self, addr: own Address, gas: u256, message: own M) -> CallOutcome
    where M: MsgVariant<Sol> + Encode<Sol>
    {
        let args = encode_calldata(<M as MsgVariant<Sol>>::SELECTOR, message)
        let mut ret = MemBuffer::empty()
        let raw = self.raw_staticcall(addr, gas, args: args.span(), ret: mut ret)
        copy_call_outcome(raw)
    }

    /// Send `value` wei to `addr` with empty calldata (Solidity
    /// `addr.call{value: value}("")`), without copying returndata or
    /// bubbling failure.
    fn send_value(mut self, addr: own Address, gas: u256, value: u256) -> RawCallOutcome {
        let mut ret = MemBuffer::empty()
        self.raw_call(addr, gas, value, args: MemSpan::empty(), ret: mut ret)
    }

    /// Perform a typed `CALL`, copying at most `ret.capacity()` bytes of
    /// returndata into `ret` without bubbling failure.
    ///
    /// Bounding the copy protects against callees that return oversized data.
    /// The outcome still reports the full returndata length.
    fn try_call_into<M>(
        mut self,
        addr: own Address,
        gas: u256,
        value: u256,
        message: own M,
        ret: mut MemBuffer,
    ) -> RawCallOutcome
    where M: MsgVariant<Sol> + Encode<Sol>
    {
        let args = encode_calldata(<M as MsgVariant<Sol>>::SELECTOR, message)
        self.raw_call(addr, gas, value, args: args.span(), ret: mut ret)
    }

    /// Perform a typed `STATICCALL`, copying at most `ret.capacity()` bytes of
    /// returndata into `ret` without bubbling failure.
    fn try_static_into<M>(
        self,
        addr: own Address,
        gas: u256,
        message: own M,
        ret: mut MemBuffer,
    ) -> RawCallOutcome
    where M: MsgVariant<Sol> + Encode<Sol>
    {
        let args = encode_calldata(<M as MsgVariant<Sol>>::SELECTOR, message)
        self.raw_staticcall(addr, gas, args: args.span(), ret: mut ret)
    }

    /// Perform a typed `DELEGATECALL` without bubbling failure.
    fn try_delegate<M>(mut self, addr: own Address, gas: u256, message: own M) -> CallOutcome
    where M: MsgVariant<Sol> + Encode<Sol>
    {
        let args = encode_calldata(<M as MsgVariant<Sol>>::SELECTOR, message)
        let mut ret = MemBuffer::empty()
        let raw = self.raw_delegatecall(addr, gas, args: args.span(), ret: mut ret)
        copy_call_outcome(raw)
    }

    fn call<M>(mut self, addr: own Address, gas: u256, value: u256, message: own M) -> M::Return
    where M: MsgVariant<Sol> + Encode<Sol>, M::Return: Decode<Sol> + AbiSize
    {
