    fn extcodecopy(
        mut self,
        _ addr: Address,
        dest: mut MemBuffer,
        dest_offset: u256,
        src_offset: u256,
        len: u256,
    ) {
        let dest_ptr = prepare_copy_destination(
            dest: mut dest,
            dest_offset,
            len,
        )
        if len == 0 {
            return
        }
        ops::extcodecopy(
            addr: addr.inner,
            dest: dest_ptr,
            offset: src_offset,
            len,
        )
        let end = dest_offset + len
        if end > dest.len() {
            dest.set_len(end)
        }
    }
    fn extcodehash(self, _ addr: Address) -> u256 {
        ops::extcodehash(addr.inner)
