#[arithmetic(unchecked)]
#[inline(always)]
fn encode_calldata<M>(_ selector: u32, _ message: own M) -> MemBuffer
where M: Encode<Sol>
{
    let selector_size = size_of<Sol::Selector>()
    let selector_word = (selector as u256) << 224
    let encoded = encode_abi_payload(message)
    let buffer = MemBuffer::alloc(selector_size + encoded.len())
    ops::mstore(addr: buffer.ptr(), value: selector_word)
    ptr::copy(
        dest: ptr::offset_bytes(buffer.ptr(), selector_size),
        source: encoded.span(),
    )
    buffer
}

/// ABI-encode a message (4-byte selector + payload) into freshly allocated
/// memory without performing a call.
pub fn encode_msg_calldata<M>(_ message: own M) -> MemBuffer
where M: MsgVariant<Sol> + Encode<Sol>
{
    encode_calldata(<M as MsgVariant<Sol>>::SELECTOR, message)
}

/// Copy the complete current returndata into a fresh owner.
pub fn copy_returndata() -> MemBuffer {
    let ret_len = ops::returndatasize()
    let buffer = MemBuffer::alloc(ret_len)
    ops::returndatacopy(dest: buffer.ptr(), offset: 0, len: ret_len)
    buffer
}

/// Revert, bubbling the current returndata payload unchanged.
pub fn bubble_last_revert() -> ! {
    let ret = copy_returndata()
    ops::revert(offset: ret.ptr(), len: ret.len())
}

/// Decode Solidity ABI data from an in-memory returndata buffer.
pub fn decode_returndata<R>(_ ret: MemSpan) -> R
    where R: Decode<Sol> + AbiSize
{
    decode_output(ret)
}

/// Perform a raw `STATICCALL` and ABI-decode the returndata on success.
///
/// This bubbles revert data on call failure and reuses the regular Solidity
/// decoder, so short or non-canonical returndata also reverts.
pub fn staticcall_decode<R>(addr: Address, gas: u256, args: MemSpan) -> R
    where R: Decode<Sol> + AbiSize
{
    let ret = MemBuffer::empty()
    let success = ops::staticcall(
        gas,
        addr: addr.inner,
        args_offset: args.ptr(),
        args_len: args.len(),
        ret_offset: ret.ptr(),
        ret_len: ret.len(),
    ) != 0

    if !success {
        bubble_last_revert()
    }

    decode_returndata(copy_returndata().span())
}

impl Call for Evm {}

#[inline(always)]
pub fn assert(_ b: own bool) {
    assert!(b)
}

/// Revert the current transaction with ABI-encoded data.
///
/// Encodes the given value using Solidity ABI encoding and reverts
/// with the encoded bytes as revert data.
pub fn revert<T>(_ value: own T) -> !
    where T: Encode<Sol> + AbiSize
{
    let result = encode_single_root_alloc<Sol, T>(value)
    ops::revert(offset: result.ptr(), len: result.len())
}

/// Revert with a Solidity-compatible custom error.
///
/// Encodes the error with its 4-byte selector prefix followed by
/// ABI-encoded fields, matching Solidity's custom error encoding.
pub fn revert_error<T>(_ error: own T) -> !
    where T: ErrorVariant<Sol> + Encode<Sol>
{
    let buffer = encode_calldata(<T as ErrorVariant<Sol>>::SELECTOR, error)
    ops::revert(offset: buffer.ptr(), len: buffer.len())
}

impl Super for Evm {}

impl ContractHost for Evm {
    type Input = CallData
    type InitInput = MemSpan

    fn input(self) -> Self::Input {
        CallData::new()
    }

    fn init_input<F>(mut self, _ runtime: F) -> Self::InitInput {
        let offset = self.code_region_offset(runtime)
        let len = self.code_region_len(runtime)
        let args_offset = offset + len
        let code_size = self.codesize()
        if code_size < args_offset {
            self.abort()
        }
        let args_len = code_size - args_offset
        let mut args = MemBuffer::alloc(args_len)
        self.codecopy(
            dest: mut args,
            dest_offset: 0,
            src_offset: args_offset,
            len: args_len,
        )
        args.span()
    }

    fn create_contract<F>(mut self, _ runtime: F) -> ! {
        let len = self.code_region_len(runtime)
        let offset = self.code_region_offset(runtime)
        let mut buffer = MemBuffer::alloc(len)
        self.codecopy(
            dest: mut buffer,
            dest_offset: 0,
            src_offset: offset,
            len,
        )
        self.return_data(data: buffer.span())
    }

    fn abort(self) -> ! {
        ops::revert_empty()
    }

    fn return_bytes(self, data: MemSpan) -> ! {
        self.return_data(data)
    }

    fn return_value<A: Abi, T>(mut self, _ value: own T) -> !
        where T: Encode<A> + AbiSize
    {
        if !T::IS_DYNAMIC {
            if T::HEAD_SIZE <= 32 {
                let out = ptr::FixedMemBuffer<32>::alloc()
                value.encode(out.ptr())
                self.return_data(
                    data: MemSpan::from_raw_parts(ptr: out.ptr(), len: T::HEAD_SIZE),
                )
            } else if T::HEAD_SIZE <= 64 {
                let out = ptr::FixedMemBuffer<64>::alloc()
                value.encode(out.ptr())
                self.return_data(
                    data: MemSpan::from_raw_parts(ptr: out.ptr(), len: T::HEAD_SIZE),
                )
            } else {
                let out = MemBuffer::alloc(T::HEAD_SIZE)
                value.encode(out.ptr())
                self.return_data(data: out.span())
            }
        } else {
            let out = encode_return_alloc<A, T>(value)
            self.return_bytes(data: out.span())
        }
    }
}

