impl ContractHost for Evm {
    type Input = CallData
    type InitInput = MemSpan

    fn input(self) -> Self::Input {
        CallData::new()
    }

    fn init_input<F>(mut self, _ runtime: F) -> Self::InitInput {
        let offset = self.code_region_offset(runtime)
        let len = self.code_region_len(runtime)
        let args_offset = offset + len
        let code_size = self.codesize()
        if code_size < args_offset {
            self.abort()
        }
        let args_len = code_size - args_offset
        let mut args = MemBuffer::alloc(args_len)
        self.codecopy(
            dest: mut args,
            dest_offset: 0,
            src_offset: args_offset,
            len: args_len,
        )
        args.span()
    }

    fn create_contract<F>(mut self, _ runtime: F) -> ! {
        let len = self.code_region_len(runtime)
        let offset = self.code_region_offset(runtime)
        let mut buffer = MemBuffer::alloc(len)
        self.codecopy(
            dest: mut buffer,
            dest_offset: 0,
            src_offset: offset,
            len,
        )
        self.return_data(data: buffer.span())
    }

    fn abort(self) -> ! {
        ops::revert_empty()
    }

    fn return_bytes(self, data: MemSpan) -> ! {
        self.return_data(data)
    }

    fn return_value<A: Abi, T>(mut self, _ value: own T) -> !
        where T: Encode<A> + AbiSize
    {
        if !T::IS_DYNAMIC {
            if T::HEAD_SIZE <= 32 {
                let out = ptr::FixedMemBuffer<32>::alloc()
                value.encode(out.ptr())
                self.return_data(
                    data: MemSpan::from_raw_parts(ptr: out.ptr(), len: T::HEAD_SIZE),
                )
            } else if T::HEAD_SIZE <= 64 {
                let out = ptr::FixedMemBuffer<64>::alloc()
                value.encode(out.ptr())
                self.return_data(
                    data: MemSpan::from_raw_parts(ptr: out.ptr(), len: T::HEAD_SIZE),
                )
            } else {
                let out = MemBuffer::alloc(T::HEAD_SIZE)
                value.encode(out.ptr())
                self.return_data(data: out.span())
            }
        } else {
            let out = encode_return_alloc<A, T>(value)
            self.return_bytes(data: out.span())
        }
    }
}

