/// encoding logic lives in the impls themselves.
pub trait EncodePacked {
    /// Exact number of bytes this value contributes.
    #[inline(always)]
    fn packed_width(self) -> u256

    /// Consume a builder, append this value, and return the builder.
    ///
    /// Passing ownership keeps generic implementations from retaining
    /// or aliasing an exclusive borrow of the builder.
    fn pack_into(own self, _ p: own Packed) -> Packed uses (mem: mut RawMem)

    /// Writes the packed bytes at `dest` and returns how many were written.
    ///
    /// `dest` must have room for `packed_width()` bytes plus 32 bytes of
    /// slack, because word-sized values are written with one full-word store.
    /// The default goes through a `Packed` builder; std's implementations
    /// store their bytes directly.
    #[inline(always)]
    fn write_packed(own self, _ dest: *u8) -> u256 uses (mem: mut RawMem) {
        let packed = self.pack_into(Packed::with_capacity(bytes: 0))
        let source = packed.buffer.span()
        ptr::copy(dest, source)
        source.len()
    }
}

/// Writes the low `width` bytes of `value` big-endian at `dest` with a single
/// word store (clobbering the following `32 - width` bytes) and returns `width`.
#[inline(always)]
pub(ingot) fn write_word_prefix(_ dest: *u8, _ value: u256, _ width: u256) -> u256 uses (mem: mut RawMem) {
    mem.mstore(addr: dest, value: value << ((32 - width) * 8))
    width
}

/// Pack a value (typically a tuple) into an exactly-sized fresh buffer.
///
/// The returned builder holds exactly the packed encoding; call
/// `keccak256`, `sha256`, or `as_bytes` on it, or keep appending.
#[inline(always)]
pub fn encode_packed<T: EncodePacked>(_ value: own T) -> Packed uses (mem: mut RawMem) {
    let width = value.packed_width()
    let mut buffer = ptr::MemBuffer::with_capacity(width + 32)
    let written = value.write_packed(buffer.ptr())
    buffer.set_len(written)
    Packed { buffer }
}

/// keccak256 of the packed encoding — the dominant consumer.
#[inline(always)]
pub fn keccak_packed<T: EncodePacked>(_ value: own T) -> u256 uses (mem: mut RawMem) {
    let width = value.packed_width()
    let buffer = ptr::alloc_bytes(width + 32)
    let written = value.write_packed(buffer)
    crypto::keccak256(MemSpan::from_raw_parts(ptr: buffer, len: written))
}

/// Imperative builder for packed byte payloads.
///
/// A bump-allocated memory buffer with byte-precise appends. Writes
/// never touch memory beyond the buffer's current capacity, and the
/// buffer grows (copy-on-grow, doubling) whenever an append would
/// exceed it — a wrong capacity hint can cost a copy, never a panic
/// or memory corruption. Growth moves the buffer, which is safe
/// because the base pointer is never exposed before the terminal ops.
pub struct Packed {
    buffer: ptr::MemBuffer,
}

